#!/usr/bin/env python3
"""Measure the matrix algebra generated by rank-one determinant updates."""

from collections import Counter
from itertools import combinations
import json
from pathlib import Path
from random import Random

from interpolation_projection_control import matrix_inverse, matrix_multiply
from paired_arrangement_mobius import candidate_rows
from paired_span_state_control import SEED, extended_panel
from signed_hankel_minrank import rank_mod
from toy_jacobian import GenusTwo


PRIME = 101


def flatten(matrix):
    return [value for row in matrix for value in row]


def identity(size):
    return [[int(row == column) for column in range(size)] for row in range(size)]


def subtract(left, right, prime):
    return [
        [(a - b) % prime for a, b in zip(lrow, rrow, strict=True)]
        for lrow, rrow in zip(left, right, strict=True)
    ]


def independent_append(basis, matrix, prime):
    vectors = [flatten(item) for item in basis]
    candidate = flatten(matrix)
    if rank_mod(vectors + [candidate], prime) == len(vectors) + 1:
        basis.append(matrix)
        return True
    return False


def generated_algebra(generators, prime):
    size = len(generators[0])
    basis = []
    independent_append(basis, identity(size), prime)
    for generator in generators:
        independent_append(basis, generator, prime)
    rounds = 0
    while len(basis) < size * size:
        rounds += 1
        snapshot = basis[:]
        changed = False
        for left in snapshot:
            for right in snapshot:
                changed |= independent_append(
                    basis, matrix_multiply(left, right, prime), prime
                )
                if len(basis) == size * size:
                    break
            if len(basis) == size * size:
                break
        if not changed:
            break
    return len(basis), rounds


def rank_one_updates(curve, panel):
    size = panel["projective_section_dimension"] + 1
    block_rank = size // 2
    reduced = dict(panel)
    reduced["split_abscissae"] = panel["split_abscissae"][:size]
    rows = candidate_rows(curve, reduced)
    base = [rows[2 * index] for index in range(size)]
    alternate = [rows[2 * index + 1] for index in range(size)]
    inverse = matrix_inverse(base, curve.p)
    dual = inverse[:block_rank]
    changed_block = [
        [
            (alternate[row][column] - base[row][column]) % curve.p
            for column in range(block_rank)
        ]
        for row in range(size)
    ]
    updates = []
    left_factors = []
    right_factors = []
    for index in range(size):
        column = [dual[row][index] for row in range(block_rank)]
        row = changed_block[index]
        left_factors.append(column)
        right_factors.append(row)
        updates.append([
            [left * right % curve.p for right in row] for left in column
        ])
    return updates, left_factors, right_factors


def analyze(curve, panel):
    updates, left_factors, right_factors = rank_one_updates(curve, panel)
    size = len(updates)
    block_rank = len(updates[0])
    full_dimension = block_rank * block_rank
    generator_span = rank_mod([flatten(update) for update in updates], curve.p)
    algebra_dimension, closure_rounds = generated_algebra(updates, curve.p)
    certificate_left = left_factors[:block_rank]
    certificate_right = right_factors[:block_rank]
    cross_pairings = [
        sum(a * b for a, b in zip(right, left, strict=True)) % curve.p
        for right in certificate_right
        for left in certificate_left
    ]
    certifying_q_subsets = 0
    for selected in combinations(range(size), block_rank):
        lefts = [left_factors[index] for index in selected]
        rights = [right_factors[index] for index in selected]
        if rank_mod(lefts, curve.p) != block_rank:
            continue
        if rank_mod(rights, curve.p) != block_rank:
            continue
        if all(
            sum(a * b for a, b in zip(right, left, strict=True)) % curve.p
            for right in rights for left in lefts
        ):
            certifying_q_subsets += 1

    first_full_prefix = None
    prefix_dimensions = []
    for length in range(1, size + 1):
        dimension, _ = generated_algebra(updates[:length], curve.p)
        prefix_dimensions.append(dimension)
        if dimension == full_dimension and first_full_prefix is None:
            first_full_prefix = length

    subset_size = size // 2
    balanced = Counter()
    for selected in combinations(range(size), subset_size):
        dimension, _ = generated_algebra(
            [updates[index] for index in selected], curve.p
        )
        balanced[dimension] += 1

    noncommuting_pairs = 0
    for left, right in combinations(updates, 2):
        if any(
            value
            for row in subtract(
                matrix_multiply(left, right, curve.p),
                matrix_multiply(right, left, curve.p),
                curve.p,
            )
            for value in row
        ):
            noncommuting_pairs += 1

    return {
        "square_slots": size,
        "compressed_matrix_size": block_rank,
        "generator_linear_span_dimension": generator_span,
        "unital_associative_algebra_dimension": algebra_dimension,
        "full_matrix_algebra_dimension": full_dimension,
        "closure_rounds": closure_rounds,
        "first_q_left_factor_rank": rank_mod(certificate_left, curve.p),
        "first_q_right_factor_rank": rank_mod(certificate_right, curve.p),
        "first_q_nonzero_cross_pairings": sum(
            value != 0 for value in cross_pairings
        ),
        "first_q_cross_pairings": block_rank * block_rank,
        "first_q_products_certify_full_matrix_algebra": (
            rank_mod(certificate_left, curve.p) == block_rank
            and rank_mod(certificate_right, curve.p) == block_rank
            and all(cross_pairings)
        ),
        "q_subsets_with_direct_full_algebra_certificate": certifying_q_subsets,
        "q_subsets": sum(1 for _ in combinations(range(size), block_rank)),
        "natural_prefix_algebra_dimensions": prefix_dimensions,
        "first_full_natural_prefix": first_full_prefix,
        "balanced_subset_size": subset_size,
        "balanced_subset_algebra_dimension_histogram": {
            str(dimension): count for dimension, count in sorted(balanced.items())
        },
        "noncommuting_update_pairs": noncommuting_pairs,
        "update_pairs": size * (size - 1) // 2,
    }


def main():
    source = json.loads(
        Path(__file__).with_name("binary_split_norm_control.json").read_text()
    )
    curve = GenusTwo(PRIME)
    panels = list(source["panels"])
    rng = Random(SEED)
    for dimension in range(8, 11):
        panel, _, _ = extended_panel(curve, dimension, rng)
        panels.append(panel)
    result = {
        "prime": PRIME,
        "genus": 2,
        "panels": [analyze(curve, panel) for panel in panels],
    }
    print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
